using FluentValidation;
namespace FintechApp.Requests.SDKSetting { public class UpdateSDKSettingRequest { public int SDKSettingID { get; set; } public string Name { get; set; } = string.Empty; public string MerchantID { get; set; } = string.Empty; public string Token { get; set; } = string.Empty; public string URL { get; set; } = string.Empty; public string PublicKey { get; set; } = string.Empty; public bool IsActive { get; set; } } public class UpdateSDKSettingRequestValidator : AbstractValidator<UpdateSDKSettingRequest> { public UpdateSDKSettingRequestValidator() { RuleFor(x => x.SDKSettingID).GreaterThan(0); } } }
